/**
 * @fileoverview TypewriterManager - Lightweight manager for typewriter effects
 * @author Eduardo Vega
 * @version 1.2.2
 * @created 2024-10-21
 * @lastmodified 2025-04-05
 */

/**
 * TypewriterEffect - Single typewriter animation effect
 */
class TypewriterEffect {
    /**
     * Creates a new typewriter effect instance
     * @param {string|HTMLElement} element - Target element or selector where text will be written
     * @param {Object} options - Configuration options
     */
    constructor(element, options = {}) {
        // Resolve element
        this.element = typeof element === 'string' ? document.querySelector(element) : element;
        if (!this.element) throw new Error('Element not found');
        
        // Clear "Loading..." text
        if (this.element.textContent === 'Loading...') this.element.textContent = '';
        
        // Setup default configuration
        this.options = {
            text: [],
            speed: 50,
            typeSpeed: 50,
            deleteSpeed: 30,
            delay: 1000,
            pauseCharacters: { ',': 500, '.': 700, '!': 700, '?': 700 },
            cursor: { character: '|', type: 'blinking' },
            mode: 'typeAndDelete',
            loop: false,
            smartPause: true,
            allowHTML: false,
            effects: {},
            callbacks: {
                onStart: null,
                onPause: null,
                onResume: null,
                onComplete: null,
                onTextChange: null
            }
        };
        
        // Merge provided options with defaults
        this._mergeOptions(options);
        
        // Initialize state
        this.state = {
            currentTextIndex: 0,
            currentCharIndex: 0,
            currentText: '',
            isTyping: false,
            isDeleting: false,
            isPaused: false,
            originalTexts: [...this.options.text],
            id: options.id || `typewriter-${Math.floor(Math.random() * 10000)}`,
            inSequence: false,
            sequenceName: null
        };
        
        // Setup containers
        this._setupContainers();
    }
    
    /**
     * Merge options with deep merge support
     * @private
     */
    _mergeOptions(options) {
        for (const key in options) {
            if (options[key] instanceof Object && !Array.isArray(options[key]) && this.options[key]) {
                for (const subKey in options[key]) {
                    this.options[key][subKey] = options[key][subKey];
                }
            } else {
                this.options[key] = options[key];
            }
        }
    }
    
    /**
     * Sets up text and cursor containers
     * @private
     */
    _setupContainers() {
        // Clear and setup element
        this.element.innerHTML = '';
        this.textContainer = document.createElement('span');
        this.element.appendChild(this.textContainer);
        
        // Add cursor if enabled
        if (this.options.cursor) {
            this.cursorContainer = document.createElement('span');
            this.cursorContainer.textContent = this.options.cursor.character;
            this.cursorContainer.style.opacity = '0.7';
            
            // Add blinking animation if needed
            if (this.options.cursor.type === 'blinking') {
                this._ensureStyles();
                this.cursorContainer.style.animation = 'typewriter-blink 0.7s infinite';
            }
            
            this.element.appendChild(this.cursorContainer);
        }
    }
    
    /**
     * Ensure global styles are injected only once
     * @private
     */
    _ensureStyles() {
        if (!document.querySelector('style[data-typewriter-blink]')) {
            const style = document.createElement('style');
            style.setAttribute('data-typewriter-blink', 'true');
            style.textContent = `
                @keyframes typewriter-blink {
                    0%, 100% { opacity: 1; }
                    50% { opacity: 0; }
                }
            `;
            document.head.appendChild(style);
        }
    }
    
    /**
     * Starts the typing animation
     * @returns {TypewriterEffect} - For method chaining
     */
    start() {
        // Reset state for clean start
        this.state.currentText = '';
        
        // Call onStart callback
        if (typeof this.options.callbacks.onStart === 'function') {
            this.options.callbacks.onStart(this);
        }
        
        if (this.state.isTyping) return this;
        
        this.state.isTyping = true;
        this.state.isPaused = false;
        this._processNextAction();
        
        return this;
    }
    
    /**
     * Process the next animation action
     * @private
     */
    _processNextAction() {
        if (!this.state.isTyping || this.state.isPaused) return;
        
        const currentText = this.options.text[this.state.currentTextIndex];
        
        // Handle different modes
        if (this.options.mode === 'typeOnly') {
            this._typeText(currentText);
        } else if (!this.state.isDeleting) {
            this._typeText(currentText);
        } else {
            this._deleteText(currentText);
        }
    }
    
    /**
     * Types text character by character
     * @private
     */
    _typeText(text) {
        if (this.state.currentCharIndex < text.length) {
            const char = text.charAt(this.state.currentCharIndex);
            
            // Add character to memory and update display
            this.state.currentText = (this.state.currentText || '') + char;
            
            if (this.options.allowHTML) {
                this.textContainer.innerHTML = this.state.currentText;
            } else {
                this.textContainer.textContent = this.state.currentText;
            }
            
            // Call onTextChange callback
            if (typeof this.options.callbacks.onTextChange === 'function') {
                this.options.callbacks.onTextChange(this.textContainer.textContent, this);
            }
            
            // Handle smart pause for punctuation
            let delay = this.options.typeSpeed;
            if (this.options.smartPause && this.options.pauseCharacters[char]) {
                delay += this.options.pauseCharacters[char];
            }
            
            this.state.currentCharIndex++;
            
            // Schedule next character
            setTimeout(() => this._processNextAction(), delay);
        } else {
            // Text completed
            if (this.options.mode === 'typeOnly') {
                this._completeSequence();
            } else {
                // Prepare for deletion
                setTimeout(() => {
                    this.state.isDeleting = true;
                    this.state.currentCharIndex = text.length;
                    this._processNextAction();
                }, this.options.delay);
            }
        }
    }
    
    /**
     * Deletes text character by character
     * @private
     */
    _deleteText(text) {
        if (this.state.currentCharIndex > 0) {
            // Remove last character from memory and update display
            this.state.currentText = this.state.currentText.slice(0, -1);
            
            if (this.options.allowHTML) {
                this.textContainer.innerHTML = this.state.currentText;
            } else {
                this.textContainer.textContent = this.state.currentText;
            }
            
            // Call onTextChange callback
            if (typeof this.options.callbacks.onTextChange === 'function') {
                this.options.callbacks.onTextChange(this.textContainer.textContent, this);
            }
            
            this.state.currentCharIndex--;
            
            // Schedule next deletion
            setTimeout(() => this._processNextAction(), this.options.deleteSpeed);
        } else {
            // Text completely deleted
            this._completeSequence();
        }
    }
    
    /**
     * Completes the current text sequence
     * @private
     */
    _completeSequence() {
        // Advance to next text
        this.state.currentTextIndex++;
        this.state.isDeleting = false;
        
        // Clear current text in memory
        this.state.currentText = '';
        
        // Check if we've reached the end of texts
        if (this.state.currentTextIndex >= this.options.text.length) {
            if (this.options.loop) {
                this.state.currentTextIndex = 0;
            } else {
                this.state.isTyping = false;
                
                // Call onComplete callback
                if (typeof this.options.callbacks.onComplete === 'function') {
                    this.options.callbacks.onComplete(this);
                }
                
                return;
            }
        }
        
        // Continue with next text
        setTimeout(() => this._processNextAction(), this.options.delay);
    }
    
    /**
     * Pauses the animation
     * @returns {TypewriterEffect} - For method chaining
     */
    pause() {
        if (this.state.isTyping && !this.state.isPaused) {
            this.state.isPaused = true;
            
            // Call onPause callback
            if (typeof this.options.callbacks.onPause === 'function') {
                this.options.callbacks.onPause(this);
            }
        }
        return this;
    }
    
    /**
     * Resumes the animation
     * @returns {TypewriterEffect} - For method chaining
     */
    resume() {
        if (this.state.isTyping && this.state.isPaused) {
            this.state.isPaused = false;
            
            // Call onResume callback
            if (typeof this.options.callbacks.onResume === 'function') {
                this.options.callbacks.onResume(this);
            }
            
            this._processNextAction();
        }
        return this;
    }
    
    /**
     * Stops the animation completely
     * @param {boolean} clearContent - Whether to clear content
     * @returns {TypewriterEffect} - For method chaining
     */
    stop(clearContent = true) {
        this.state.isTyping = false;
        this.state.isPaused = false;
        this.state.currentText = '';
        
        if (clearContent) {
            this.textContainer.textContent = '';
            if (this.options.allowHTML) {
                this.textContainer.innerHTML = '';
            }
        }
        
        this.state.currentTextIndex = 0;
        this.state.currentCharIndex = 0;
        return this;
    }
    
    /**
     * Resets the animation
     * @returns {TypewriterEffect} - For method chaining
     */
    reset() {
        this.stop(true);
        this.options.text = [...this.state.originalTexts];
        this.state.currentText = '';
        this.start();
        return this;
    }
    
    /**
     * Adds text to the queue
     * @param {string|string[]} text - Text or array of texts to add
     * @returns {TypewriterEffect} - For method chaining
     */
    addText(text) {
        if (Array.isArray(text)) {
            this.options.text.push(...text);
        } else {
            this.options.text.push(text);
        }
        return this;
    }
    
    /**
     * Skips to the next text
     * @returns {TypewriterEffect} - For method chaining
     */
    skip() {
        if (this.state.isTyping) {
            this.state.currentTextIndex++;
            if (this.state.currentTextIndex >= this.options.text.length) {
                this.state.currentTextIndex = this.options.loop ? 0 : this.options.text.length - 1;
            }
            this.state.currentCharIndex = 0;
            this.state.isDeleting = false;
            this.state.currentText = '';
            
            // Clear display
            this.textContainer.textContent = '';
            if (this.options.allowHTML) {
                this.textContainer.innerHTML = '';
            }
            
            this._processNextAction();
        }
        return this;
    }
    
    /**
     * Changes the texts to display
     * @param {string[]} newTexts - New texts
     * @param {boolean} restart - Whether to restart the animation
     * @returns {TypewriterEffect} - For method chaining
     */
    changeTexts(newTexts, restart = true) {
        this.options.text = newTexts;
        this.state.originalTexts = [...newTexts];
        this.state.currentTextIndex = 0;
        this.state.currentCharIndex = 0;
        this.state.currentText = '';
        
        if (restart) {
            this.stop(true);
            this.start();
        }
        
        return this;
    }
    
    /**
     * Updates configuration options
     * @param {Object} newOptions - New options
     * @returns {TypewriterEffect} - For method chaining
     */
    updateOptions(newOptions) {
        this._mergeOptions(newOptions);
        return this;
    }
    
    /**
     * Destroys the instance and cleans up
     */
    destroy() {
        this.stop(true);
        if (this.textContainer) this.element.removeChild(this.textContainer);
        if (this.cursorContainer) this.element.removeChild(this.cursorContainer);
        this.state.currentText = '';
    }
    
    /**
     * Gets the current element
     * @returns {HTMLElement} - The current element
     */
    getElement() {
        return this.element;
    }
    
    /**
     * Gets the instance ID
     * @returns {string} - The instance ID
     */
    getId() {
        return this.state.id;
    }
    
    /**
     * Gets current typing state
     * @returns {Object} - Current state
     */
    getState() {
        return { ...this.state };
    }
}

/**
 * TypewriterManager - Manager class for multiple typewriter effects
 */
class TypewriterManager {
    /**
     * Creates a new TypewriterManager instance
     * @param {Object} globalOptions - Default options for all typewriter instances
     */
    constructor(globalOptions = {}) {
        this.instances = new Map();
        this.globalOptions = globalOptions;
        this.sequences = {};
        this.activeSequences = new Set();
    }
    
    /**
     * Creates a new typewriter effect
     * @param {string|HTMLElement} element - Target element or selector 
     * @param {Object} options - Instance options
     * @returns {TypewriterEffect} - The created typewriter effect
     */
    create(element, options = {}) {
        const mergedOptions = { ...this.globalOptions, ...options };
        const instance = new TypewriterEffect(element, mergedOptions);
        this.instances.set(instance.getId(), instance);
        return instance;
    }
    
    /**
     * Gets a typewriter instance by ID
     * @param {string} id - Instance ID
     * @returns {TypewriterEffect|null} - The typewriter instance or null
     */
    get(id) {
        return this.instances.get(id) || null;
    }
    
    /**
     * Gets all instances
     * @returns {Map} - Map of all instances
     */
    getAll() {
        return this.instances;
    }
    
    /**
     * Helper to execute a method on an instance
     * @private
     */
    _executeOnInstance(id, method, args = []) {
        const instance = this.instances.get(id);
        if (instance && typeof instance[method] === 'function') {
            instance[method](...args);
        }
        return this;
    }
    
    /**
     * Helper to execute a method on all instances
     * @private
     */
    _executeOnAll(method, args = []) {
        this.instances.forEach(instance => {
            if (typeof instance[method] === 'function') {
                instance[method](...args);
            }
        });
        return this;
    }
    
    // Instance control methods
    start(id) { return this._executeOnInstance(id, 'start'); }
    startAll() { return this._executeOnAll('start'); }
    pause(id) { return this._executeOnInstance(id, 'pause'); }
    pauseAll() { return this._executeOnAll('pause'); }
    resume(id) { return this._executeOnInstance(id, 'resume'); }
    resumeAll() { return this._executeOnAll('resume'); }
    stop(id, clearContent = true) { return this._executeOnInstance(id, 'stop', [clearContent]); }
    stopAll(clearContent = true) { return this._executeOnAll('stop', [clearContent]); }
    
    /**
     * Removes an instance
     * @param {string} id - Instance ID
     * @returns {TypewriterManager} - For method chaining
     */
    remove(id) {
        const instance = this.instances.get(id);
        if (instance) {
            instance.destroy();
            this.instances.delete(id);
        }
        return this;
    }
    
    /**
     * Removes all instances
     * @returns {TypewriterManager} - For method chaining
     */
    removeAll() {
        this.instances.forEach(instance => instance.destroy());
        this.instances.clear();
        this.sequences = {};
        this.activeSequences.clear();
        return this;
    }
    
    /**
     * Updates global options
     * @param {Object} newOptions - New global options
     * @returns {TypewriterManager} - For method chaining
     */
    updateGlobalOptions(newOptions) {
        this.globalOptions = { ...this.globalOptions, ...newOptions };
        return this;
    }
    
    /**
     * Updates options for a specific instance
     * @param {string} id - Instance ID
     * @param {Object} options - New options
     * @returns {TypewriterManager} - For method chaining
     */
    updateInstanceOptions(id, options) {
        return this._executeOnInstance(id, 'updateOptions', [options]);
    }
    
    /**
     * Creates a sequence of typewriter effects
     * @param {string} sequenceName - Name of the sequence
     * @param {Array} sequence - Array of instance IDs in sequence order
     * @param {number} delay - Delay between effects in ms
     * @returns {TypewriterManager} - For method chaining
     */
    createSequence(sequenceName, sequence, delay = 500) {
        this.sequences[sequenceName] = {
            ids: sequence,
            delay,
            isPlaying: false,
            isPaused: false,
            currentIndex: 0,
            currentInstance: null
        };
        return this;
    }
    
    /**
     * Plays a sequence of typewriter effects
     * @param {string} sequenceName - Name of the sequence
     * @returns {TypewriterManager} - For method chaining
     */
    playSequence(sequenceName) {
        const sequence = this.sequences[sequenceName];
        if (!sequence || sequence.isPlaying) return this;
        
        // Reset sequence state
        sequence.isPlaying = true;
        sequence.isPaused = false;
        sequence.currentIndex = 0;
        
        // Add to active sequences
        this.activeSequences.add(sequenceName);
        
        // Process sequence steps
        const playNext = () => {
            // Skip if sequence is paused or stopped
            if (!sequence.isPlaying || sequence.isPaused) return;
            
            if (sequence.currentIndex < sequence.ids.length) {
                const id = sequence.ids[sequence.currentIndex];
                const instance = this.instances.get(id);
                
                if (instance) {
                    // Clean up the instance
                    instance.stop(true);
                    
                    // Mark this instance as part of a sequence
                    instance.state.inSequence = true;
                    instance.state.sequenceName = sequenceName;
                    
                    // Remember current instance
                    sequence.currentInstance = instance;
                    
                    // Store original callback
                    const originalCallback = instance.options.callbacks.onComplete;
                    
                    // Set up callback to advance sequence
                    instance.options.callbacks.onComplete = (inst) => {
                        // Call original callback
                        if (typeof originalCallback === 'function') {
                            originalCallback(inst);
                        }
                        
                        // Only advance if sequence is still playing
                        if (sequence.isPlaying && !sequence.isPaused) {
                            sequence.currentIndex++;
                            setTimeout(() => playNext(), sequence.delay);
                        }
                    };
                    
                    // Start the instance
                    instance.start();
                } else {
                    // Skip missing instances
                    sequence.currentIndex++;
                    setTimeout(playNext, 0);
                }
            } else {
                // End of sequence
                sequence.isPlaying = false;
                sequence.isPaused = false;
                sequence.currentIndex = 0;
                sequence.currentInstance = null;
                this.activeSequences.delete(sequenceName);
            }
        };
        
        // Start the sequence processing
        playNext();
        return this;
    }
    
    /**
     * Pauses a sequence
     * @param {string} sequenceName - Name of the sequence
     * @returns {TypewriterManager} - For method chaining
     */
    pauseSequence(sequenceName) {
        const sequence = this.sequences[sequenceName];
        if (sequence && sequence.isPlaying) {
            // Mark sequence as paused
            sequence.isPaused = true;
            
            // If we have a current instance, pause it
            if (sequence.currentInstance) {
                sequence.currentInstance.pause();
            }
        }
        return this;
    }
    
    /**
     * Resumes a paused sequence
     * @param {string} sequenceName - Name of the sequence
     * @returns {TypewriterManager} - For method chaining
     */
    resumeSequence(sequenceName) {
        const sequence = this.sequences[sequenceName];
        if (sequence && sequence.isPlaying && sequence.isPaused) {
            // Mark sequence as no longer paused
            sequence.isPaused = false;
            
            // If we have a current instance, resume it
            if (sequence.currentInstance && sequence.currentInstance.getState().isPaused) {
                sequence.currentInstance.resume();
            } else {
                // No current instance or not paused - restart from current position
                this.playSequence(sequenceName);
            }
        }
        return this;
    }
    
    /**
     * Stops a sequence
     * @param {string} sequenceName - Name of the sequence
     * @returns {TypewriterManager} - For method chaining
     */
    stopSequence(sequenceName) {
        const sequence = this.sequences[sequenceName];
        if (sequence) {
            // Mark sequence as stopped
            sequence.isPlaying = false;
            sequence.isPaused = false;
            
            // Stop all instances in the sequence
            if (sequence.ids && Array.isArray(sequence.ids)) {
                sequence.ids.forEach(id => {
                    const instance = this.instances.get(id);
                    if (instance) {
                        // Clear sequence flags
                        instance.state.inSequence = false;
                        instance.state.sequenceName = null;
                        
                        // Stop the instance
                        if (instance.getState().isTyping) {
                            instance.stop(true);
                        }
                    }
                });
            }
            
            // Clean up
            sequence.currentInstance = null;
            this.activeSequences.delete(sequenceName);
        }
        return this;
    }
    
    /**
     * Gets the active instance in a sequence
     * @param {string} sequenceName - Name of the sequence
     * @returns {TypewriterEffect|null} - The active instance or null
     */
    getActiveSequenceInstance(sequenceName) {
        const sequence = this.sequences[sequenceName];
        return sequence ? sequence.currentInstance : null;
    }
    
    /**
     * Creates typewriter effects for multiple elements
     * @param {string} selector - CSS selector for target elements 
     * @param {Object} options - Options for instances
     * @param {boolean} startImmediately - Whether to start immediately
     * @returns {Array} - Array of created instance IDs
     */
    createBulk(selector, options = {}, startImmediately = false) {
        const elements = document.querySelectorAll(selector);
        const ids = [];
        
        elements.forEach((element, index) => {
            const elementOptions = {
                ...options,
                id: options.id ? `${options.id}-${index}` : undefined
            };
            
            // Handle text generator function
            if (typeof options.textGenerator === 'function') {
                elementOptions.text = options.textGenerator(element, index);
            }
            
            // Create and store instance
            const instance = this.create(element, elementOptions);
            ids.push(instance.getId());
            
            if (startImmediately) {
                instance.start();
            }
        });
        
        return ids;
    }
    
    /**
     * Synchronizes multiple typewriter effects to run in parallel
     * @param {Array} ids - Array of instance IDs
     * @returns {TypewriterManager} - For method chaining
     */
    syncStart(ids) {
        // Reset all specified instances
        ids.forEach(id => this.stop(id, true));
        
        // Start all specified instances
        ids.forEach(id => this.start(id));
        
        return this;
    }
}

// For backward compatibility with TypewriterJS
class TypewriterJS extends TypewriterEffect {
    constructor(element, options = {}) {
        super(element, options);
    }
}

export { TypewriterManager, TypewriterEffect, TypewriterJS };